const pages=[...document.querySelectorAll('[data-page]')];
const routeButtons=[...document.querySelectorAll('[data-route]')];
function navigate(route){
  const target=document.querySelector(`[data-page="${route}"]`)||document.querySelector('[data-page="home"]');
  pages.forEach(p=>p.classList.toggle('active',p===target));
  routeButtons.forEach(b=>b.classList.toggle('active',b.dataset.route===route&&(!b.classList.contains('brand'))));
  history.replaceState(null,'',`#${route}`);window.scrollTo({top:0,behavior:'smooth'});target.focus?.();
}
routeButtons.forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.route)));
const toast=document.querySelector('.toast');let toastTimer;
function showToast(message){toast.textContent=message;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),2200)}
document.querySelectorAll('[data-toast]').forEach(b=>b.addEventListener('click',()=>showToast(b.dataset.toast)));
document.querySelectorAll('.subject-tabs button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.subject-tabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');showToast(`${b.textContent} sélectionné`)}));
const sliders=[...document.querySelectorAll('.score-inputs input')];
function updateScore(){const values=sliders.map(s=>Number(s.value));const avg=values.reduce((a,b)=>a+b,0)/values.length;document.querySelector('#average').textContent=avg.toFixed(2).replace('.',',');document.querySelector('#gap').textContent=`${Math.max(0,16-avg).toFixed(2).replace('.',',')} point${16-avg>1?'s':''}`;sliders.forEach(s=>s.parentElement.querySelector('output').textContent=String(s.value).replace('.',','))}
sliders.forEach(s=>s.addEventListener('input',updateScore));

const tracks={
  sma:{name:'Sciences Mathématiques A',short:'Sciences Maths A',subjects:['Mathématiques','Physique-Chimie','Sciences de la Vie et de la Terre','Philosophie','Langue étrangère']},
  smb:{name:'Sciences Mathématiques B',short:'Sciences Maths B',subjects:['Mathématiques','Physique-Chimie','Sciences de l’ingénieur','Philosophie','Langue étrangère']},
  pc:{name:'Sciences Physiques',short:'Sciences Physiques',subjects:['Physique-Chimie','Mathématiques','Sciences de la Vie et de la Terre','Philosophie','Langue étrangère']},
  svt:{name:'Sciences de la Vie et de la Terre',short:'SVT',subjects:['Sciences de la Vie et de la Terre','Mathématiques','Physique-Chimie','Philosophie','Langue étrangère']},
  ste:{name:'Sciences et Technologies Électriques',short:'Technologies Électriques',subjects:['Sciences de l’ingénieur','Mathématiques','Physique-Chimie','Philosophie','Langue étrangère']},
  stm:{name:'Sciences et Technologies Mécaniques',short:'Technologies Mécaniques',subjects:['Sciences de l’ingénieur','Mathématiques','Physique-Chimie','Philosophie','Langue étrangère']},
  agro:{name:'Sciences Agronomiques',short:'Sciences Agronomiques',subjects:['Sciences agronomiques','Sciences de la Vie et de la Terre','Mathématiques','Physique-Chimie','Philosophie','Langue étrangère']}
};
const trackGrid=document.querySelector('#trackGrid');
Object.entries(tracks).forEach(([id,track],index)=>{trackGrid.insertAdjacentHTML('beforeend',`<button type="button" class="track-choice" data-track="${id}"><span>${String(index+1).padStart(2,'0')}</span><b>${track.name}</b><i>↗</i></button>`)});
let setup={step:1,role:'',level:'2bac',track:'',subjects:[]};
const panels=[...document.querySelectorAll('.setup-panel')],next=document.querySelector('#setupNext'),back=document.querySelector('#setupBack');
function syncSetup(){panels.forEach(p=>p.classList.toggle('active',Number(p.dataset.step)===setup.step));document.querySelector('#stepCount').textContent=`${setup.step}/4`;document.querySelector('#setupProgress').style.width=`${setup.step*25}%`;back.style.visibility=setup.step===1?'hidden':'visible';next.innerHTML=setup.step===4?'Créer mon espace <span>→</span>':'Continuer <span>→</span>';next.disabled=setup.step===1?!setup.role:setup.step===3?!setup.track:setup.step===4?!setup.subjects.length:false}
document.querySelectorAll('[data-role]').forEach(b=>b.addEventListener('click',()=>{setup.role=b.dataset.role;document.querySelectorAll('[data-role]').forEach(x=>x.classList.toggle('selected',x===b));syncSetup()}));
document.querySelectorAll('[data-track]').forEach(b=>b.addEventListener('click',()=>{setup.track=b.dataset.track;setup.subjects=[];document.querySelectorAll('[data-track]').forEach(x=>x.classList.toggle('selected',x===b));syncSetup()}));
function renderSubjects(){const grid=document.querySelector('#subjectGrid');grid.innerHTML='';(tracks[setup.track]?.subjects||[]).forEach((name,index)=>grid.insertAdjacentHTML('beforeend',`<button type="button" class="subject-choice" data-subject="${name}"><span>${String(index+1).padStart(2,'0')}</span><b>${name}</b><i>+</i></button>`));grid.querySelectorAll('[data-subject]').forEach(b=>b.addEventListener('click',()=>{const name=b.dataset.subject;b.classList.toggle('selected');setup.subjects=b.classList.contains('selected')?[...setup.subjects,name]:setup.subjects.filter(x=>x!==name);b.querySelector('i').textContent=b.classList.contains('selected')?'✓':'+';syncSetup()}))}
back.addEventListener('click',()=>{setup.step=Math.max(1,setup.step-1);syncSetup()});
next.addEventListener('click',()=>{if(setup.step<4){setup.step++;if(setup.step===4)renderSubjects();syncSetup();return}localStorage.setItem('nqtaProfile',JSON.stringify(setup));launchApp(setup)});
function emptyCard(title,text,action=''){return `<article class="empty-card"><span class="empty-orbit"></span><h2>${title}</h2><p>${text}</p>${action?`<button class="primary">${action} <span>→</span></button>`:''}</article>`}
function renderCleanApp(profile){const track=tracks[profile.track];document.querySelector('.crumb b').textContent=track.short;document.querySelector('.profile-mini div b').textContent=profile.role==='teacher'?'Espace professeur':'Espace élève';document.querySelector('.profile-mini small').textContent=track.short;document.querySelector('#home').innerHTML=`<div class="clean-head"><div><span class="eyebrow">VOTRE ESPACE EST PRÊT</span><h1>${profile.role==='teacher'?'Construisez votre suivi pédagogique.':'Construisez votre point de départ.'}</h1><p>${track.name} · 2e année Baccalauréat</p></div><span class="verified-pill">Référentiel annuel à synchroniser</span></div><div class="clean-grid">${emptyCard('Aucune estimation pour le moment','Le niveau apparaîtra après un premier diagnostic.','Lancer le diagnostic')}${emptyCard('Aucun plan généré','Le plan quotidien sera construit à partir de vos résultats réels.','Créer mon premier plan')}</div><section class="selected-subjects"><span class="eyebrow">MATIÈRES SÉLECTIONNÉES</span><div>${profile.subjects.map(s=>`<span>${s}</span>`).join('')}</div></section>`;document.querySelector('#today').innerHTML=`<div class="page-head"><div><span class="eyebrow">MA SESSION</span><h1>Aucune session planifiée.</h1><p>Votre première session sera générée après le diagnostic.</p></div></div>${emptyCard('Commencer sans données fictives','Choisissez une matière et indiquez votre temps disponible pour créer une vraie session.','Configurer une session')}`;document.querySelector('#learn').innerHTML=`<div class="page-head"><div><span class="eyebrow">APPRENDRE</span><h1>Vos matières.</h1><p>Les chapitres apparaîtront après synchronisation et validation du cadre de référence annuel.</p></div></div><div class="subject-clean-grid">${profile.subjects.map(s=>`<article><span>MATIÈRE</span><h2>${s}</h2><small>Contenu officiel à synchroniser</small></article>`).join('')}</div>`;document.querySelector('#annales').innerHTML=`<div class="page-head"><div><span class="eyebrow">ANNALES</span><h1>Aucune annale importée.</h1><p>Seuls les sujets officiels vérifiés seront affichés ici.</p></div></div>${emptyCard('Bibliothèque vide','Importez ou synchronisez les sujets officiels correspondant à cette filière.')}`;document.querySelector('#progress').innerHTML=`<div class="page-head"><div><span class="eyebrow">MON NIVEAU</span><h1>Pas encore assez de données.</h1><p>Les estimations nécessitent des réponses réelles, jamais des valeurs de démonstration.</p></div></div>${emptyCard('Votre progression commencera ici','Terminez un diagnostic ou un premier exercice pour établir votre point de départ.','Faire le diagnostic')}`;document.querySelector('#score').innerHTML=`<div class="page-head"><div><span class="eyebrow">OBJECTIF BAC</span><h1>Objectif non défini.</h1><p>Les coefficients ne seront activés qu’après validation du référentiel de l’année scolaire.</p></div></div>${emptyCard('Aucune simulation disponible','Définissez d’abord votre objectif et validez les coefficients officiels de votre filière.','Définir mon objectif')}`}
function launchApp(profile){renderCleanApp(profile);document.body.classList.remove('onboarding-active');document.querySelector('#onboarding').hidden=true;navigate('home')}
const savedProfile=localStorage.getItem('nqtaProfile');
if(savedProfile){try{launchApp(JSON.parse(savedProfile))}catch{document.body.classList.add('onboarding-active')}}else{document.body.classList.add('onboarding-active');syncSetup()}
